// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    address originalOwner;

    function setUp() public {
        c = new SimpleWallet();
        originalOwner = c.owner();
    }

    function testFuzz_property(address caller, address target, uint256 amount) public {
        vm.assume(caller != originalOwner);
        vm.assume(target != address(c));
        amount = bound(amount, 0, type(uint128).max);
        vm.deal(caller, amount);

        Reverter reverter = new Reverter();
        address adversarialTarget = address(reverter);

        vm.prank(caller);
        bool ok;
        try c.sendMoney(adversarialTarget, amount) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
